# frozen_string_literal: true

# A thread-safe integer counter backed by a Mutex.
class Counter
  def initialize(initial = 0)
    @value = initial
    @mutex = Mutex.new
  end

  def value
    @mutex.synchronize { @value }
  end

  def increment(by = 1)
    @mutex.synchronize { @value += by }
  end

  def decrement(by = 1)
    @mutex.synchronize { @value -= by }
  end

  def reset(to = 0)
    @mutex.synchronize { @value = to }
  end

  # Atomically yields the current value and stores the block's result.
  def update
    @mutex.synchronize { @value = yield(@value) }
  end

  def to_i
    value
  end

  def inspect
    "#<#{self.class.name} value=#{value}>"
  end
end

if $PROGRAM_NAME == __FILE__
  counter = Counter.new
  threads = Array.new(10) { Thread.new { 10_000.times { counter.increment } } }
  threads.each(&:join)
  puts counter.value # => 100000
end
